(function(root){'use strict';
function capture(){const ctx=root.MT_LEARNING_CYCLE_CONTEXT.read();if(root.MT_MOLLIER_INPUTS)ctx.inputs=root.MT_MOLLIER_INPUTS();if(root.MT_CARGO_UI)ctx.inputs=root.MT_CARGO_UI.snapshot().inputs;return ctx;}
function snapshot(){if(root.MT_EDUCATION_SNAPSHOT)return root.MT_EDUCATION_SNAPSHOT();if(root.MT_EXAMPLE_UI)return root.MT_EXAMPLE_UI.snapshot();if(root.MT_EXPLORER_UI)return root.MT_EXPLORER_UI.snapshot();if(root.MT_CARGO_UI)return root.MT_CARGO_UI.snapshot();if(root.MT_MOLLIER_SNAPSHOT)return root.MT_MOLLIER_SNAPSHOT();return root.MT_LAB_SNAPSHOT(capture().id);}
const curve=(id,xLabel,yLabel,series)=>({id,xLabel,yLabel,series});
function evaluate(id,x){for(const ui of [root.MT_MODEL_UI,root.MT_EXAMPLE_UI,root.MT_EXPLORER_UI])if(ui)return ui.evaluate(x);const M=root.MT_LABS;
 if(id==='stability'){const z=M.stability(x);return {results:{'Corrected GM (m)':z.gm,'Free-surface correction (m)':z.fsc,'KG after relocation (m)':z.movedKG,'Maximum sampled GZ (m)':z.maximum.gz,'Signed area 0–30° (m·rad)':z.area30,'Initial positive range ends (°)':z.zero},curves:[curve('gz','Heel (°)','GZ (m)',[{name:'Corrected GZ',points:z.curve.map(p=>({x:p.angle,y:p.gz}))}])]};}
 if(id==='engine'){const z=M.engine(x),rows=Array.from({length:30},(_,i)=>{const speed=Math.max(1,Math.min(6000,x.rpm*(.5+i/29)));return{x:speed,y:M.engine({...x,rpm:speed}).brake};});return{results:{'Brake power (kW)':z.brake,'Indicated power (kW)':z.indicated,'Fuel flow (kg/h)':z.fuel,'SFOC (g/kWh)':z.sfoc,'Swept volume (L)':z.volume*1000,'Mean piston speed (m/s)':z.pistonSpeed},curves:[curve('speed','Engine speed (rpm)','Brake power (kW)',[{name:'Constant entered mean effective pressure',points:rows}])]};}
 if(id==='controls'){const s=x.signal,v=M.scale(s.value,s.lrv,s.urv,s.inverse==='true'),rows=M.pid(x.pid),end=rows.at(-1);return{results:{['Signal output ('+(s.inverse==='true'?'engineering units':'mA')+')']:v,'PV at 180 s (%)':end.pv,'Controller output at 180 s (%)':end.u,'Error at 180 s (percentage points)':end.sp-end.pv},curves:[curve('pid','Time (s)','SP, PV and output (%)',['sp','pv','u'].map(key=>({name:key,points:rows.map(p=>({x:p.t,y:p[key]}))})))]};}
 if(id==='cargo'){const z=root.MT_CARGO.calculate(x),r=z.final;return{results:{'Final displacement (t)':r.displacement,'Final KG (m)':r.kg,'Final LCG (m)':r.lcg,'Final TCG (m)':r.tcg,'Final FSC (m)':r.fsc,'Illustrative GM (m)':r.gm},curves:[curve('kg','Completed stage','KG (m)',[{name:'KG',points:z.rows.map((p,i)=>({x:i,y:p.kg}))}])]};}
 if(id==='mollier'){const M=root.MT_MOLLIER_MODEL,states={};for(const key of ['a','b']){const s=x[key];states[key]=s.phase==='wet'?M.stateAt(s.p,s.x):M.superheated(s.p,s.T);}let path=[states.a,states.b];if(x.process){const z=M.expansion(states.a,x.b.p,x.process.mode,x.process.efficiency);states.b=z.outlet;if(!states.b)throw Error('Process endpoint unavailable.');path=z.path?.length?z.path:[states.a,states.b];}
 const a=states.a,b=states.b;return{results:{'State A · h (kJ/kg)':a.h,'State A · s (kJ/kg/K)':a.s,'State A · T (°C)':a.T,'State B · h (kJ/kg)':b.h,'State B · s (kJ/kg/K)':b.s,'State B · T (°C)':b.T,'h_A − h_B (kJ/kg)':a.h-b.h,'s_B − s_A (kJ/kg/K)':b.s-a.s},curves:[curve('hs','Entropy (kJ/kg/K)','Enthalpy (kJ/kg)',[{name:x.process?'Solved process':'Endpoint connector',points:path.map(p=>({x:p.s,y:p.h}))}])]};}
 throw Error('This module has no analysis adapter.');
}
root.MT_ANALYSIS_ADAPTER={capture,snapshot,evaluate};
})(window);
